const FEATURES = DATA.features;
const PLAYERS = DATA.players;
const allPairsCount = (PLAYERS.length * (PLAYERS.length - 1)) / 2;

// Each player's `.z` vector is their projection onto the top
// DATA.pcaComponents principal components of the league's real covariance
// structure — z-scored stats run through PCA, keeping the components that
// explain ~95% of real variance (the rest is noise). Deliberately NOT
// whitened: whitening would force every retained component to contribute
// equally regardless of how much real variance it explains, which dilutes
// the strongest signal (overall production, ~40% of real variance) down to
// the same weight as a minor axis (~2%). Tested both ways on real data —
// PCA-without-whitening reliably produces recognizable comps (Curry <->
// Mitchell/Murray, Giannis <-> Jokić <-> Embiid); whitening pulled Norman
// Powell back next to Anthony Edwards and separated Jokić from Giannis, the
// exact problem this project kept circling back to. No manual weights
// either — PCA's eigenvalue-scaled magnitude is the only "weighting" here,
// learned directly from the data.
//
// Similarity is cosine similarity on that space — nothing else. Cosine
// compares the *shape* of two statistical profiles regardless of overall
// production level, which fits "player archetype" better than a distance
// metric: a 30/8/5 season and a 25/7/4 season have a very similar shape
// even though the raw numbers differ.
function cosineSimilarity(a, b) {
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < a.z.length; i++) {
    dot += a.z[i] * b.z[i];
    normA += a.z[i] * a.z[i];
    normB += b.z[i] * b.z[i];
  }
  return dot / (Math.sqrt(normA) * Math.sqrt(normB) + 1e-12);
}

// Percentile lookup over the real distribution of all pairwise cosine
// similarities in this dataset — used for the tier label under each name,
// not to transform the score itself.
const COSINE_PERCENTILES = DATA.cosinePercentiles;

function cosinePercentile(cos) {
  const pts = COSINE_PERCENTILES;
  if (cos <= pts[0]) return 0;
  if (cos >= pts[pts.length - 1]) return 100;
  let lo = 0, hi = pts.length - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (pts[mid] <= cos) lo = mid; else hi = mid;
  }
  const span = pts[hi] - pts[lo];
  const frac = span > 0 ? (cos - pts[lo]) / span : 0;
  return (lo + frac) / 10;
}

function comparePlayers(a, b) {
  const cosine = cosineSimilarity(a, b);
  const score = cosine * 100; // Similarity Score = cosine similarity × 100.
  const percentile = cosinePercentile(cosine);
  return { cosine, score, percentile };
}

function findTopMatches(anchor, n = 10) {
  const others = PLAYERS.filter(p => p.id !== anchor.id);
  return others
    .map(p => ({ player: p, ...comparePlayers(anchor, p) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, n)
    .map((r, i) => ({ ...r, rank: i + 1, tier: matchTier(r.percentile) }));
}

function matchTier(percentile) {
  if (percentile >= 99) return { label: 'Elite statistical match', sub: 'top 1% of all comparisons', cls: 'tier-elite' };
  if (percentile >= 95) return { label: 'Excellent comparison', sub: 'top 5% of all comparisons', cls: 'tier-excellent' };
  if (percentile >= 90) return { label: 'Strong comparison', sub: 'top 10% of all comparisons', cls: 'tier-strong' };
  if (percentile >= 75) return { label: 'Good comparison', sub: 'top 25% of all comparisons', cls: 'tier-good' };
  return { label: 'Loose comparison', sub: `${percentile.toFixed(0)}th percentile of all comparisons`, cls: 'tier-loose' };
}

// Only the essentials are shown in the UI — the algorithm matches on all 15
// weighted features; this list is what's worth a human's eyes.
const STAT_ROWS = [
  { key: 'PPG', label: 'PTS', fmt: v => v.toFixed(1) },
  { key: 'RPG', label: 'REB', fmt: v => v.toFixed(1) },
  { key: 'APG', label: 'AST', fmt: v => v.toFixed(1) },
  { key: 'SPG', label: 'STL', fmt: v => v.toFixed(1) },
  { key: 'BPG', label: 'BLK', fmt: v => v.toFixed(1) },
  { key: 'MPG', label: 'MIN', fmt: v => v.toFixed(1), neutral: true },
  { key: 'TS_PCT', label: 'TS%', fmt: v => (v * 100).toFixed(1), scale: 100 },
  { key: 'USG_PCT', label: 'USG%', fmt: v => v.toFixed(1), neutral: true },
  { key: 'AST_PCT', label: 'AST%', fmt: v => v.toFixed(1) },
  { key: 'TRB_PCT', label: 'REB%', fmt: v => v.toFixed(1) },
  { key: 'TOV_PCT', label: 'TOV%', fmt: v => v.toFixed(1), invert: true },
  { key: '3PAr', label: '3PA RATE', fmt: v => (v * 100).toFixed(1), scale: 100, neutral: true },
  { key: 'FTr', label: 'FTA RATE', fmt: v => (v * 100).toFixed(1), scale: 100, neutral: true },
  { key: 'PER', label: 'PER', fmt: v => v.toFixed(1) },
  { key: 'BPM', label: 'BPM', fmt: v => v.toFixed(1) },
  { key: 'WS_48', label: 'WS/48', fmt: v => v.toFixed(3) },
];

const STAT_STD_DEVS = DATA.statStdDevs;
const SIGNIFICANCE_FRACTION = 0.25; // a diff must clear 1/4 of the league-wide std dev to be color-highlighted

function StatDelta({ statKey, label, anchorVal, compVal, fmt, invert, neutral, scale = 1 }) {
  const diff = compVal - anchorVal;
  const std = STAT_STD_DEVS[statKey];
  const isSignificant = !neutral && std && Math.abs(diff) > SIGNIFICANCE_FRACTION * std;

  let color = 'var(--ink-muted)';
  if (isSignificant) {
    const better = invert ? diff < 0 : diff > 0;
    color = better ? 'var(--court)' : 'var(--foul)';
  }
  const sign = diff > 0 ? '+' : '';
  const displayDiff = (diff * scale).toFixed(1);

  return (
    <div className="stat-cell">
      <div className="stat-label">{label}</div>
      <div className="stat-value">{fmt(compVal)}</div>
      <div className="stat-diff" style={{ color }}>{sign}{displayDiff}</div>
    </div>
  );
}

function Gauge({ score, rank }) {
  const r = 30;
  const circ = 2 * Math.PI * r;
  const pct = score / 100;
  const offset = circ * (1 - pct);
  return (
    <div className="gauge-wrap">
      <svg width="72" height="72" viewBox="0 0 72 72">
        <circle cx="36" cy="36" r={r} fill="none" stroke="var(--line)" strokeWidth="5" />
        <circle
          cx="36" cy="36" r={r} fill="none"
          stroke="var(--amber)" strokeWidth="5" strokeLinecap="round"
          strokeDasharray={circ} strokeDashoffset={offset}
          transform="rotate(-90 36 36)"
          style={{ transition: 'stroke-dashoffset 700ms cubic-bezier(.4,0,.2,1)' }}
        />
      </svg>
      <div className="gauge-num">
        <span className="gauge-score">{score.toFixed(0)}</span>
        <span className="gauge-pct">%</span>
      </div>
    </div>
  );
}

// Small SVG diagram showing the vector between two players in the same
// reduced (PCA) statistical space that powers the 3D explorer. Each row gets
// its own local scale so the connecting vector is always clearly visible,
// regardless of whether the true gap is tiny or large.
function VectorDiagram({ anchor, match }) {
  const W = 168, H = 78, PAD = 20;
  const [ax, ay] = anchor.pca;
  const [mx, my] = match.player.pca;
  const dx = mx - ax, dy = my - ay;
  const mag = Math.max(Math.hypot(dx, dy), 0.75);
  const scale = (Math.min(W, H) / 2 - PAD) / mag;
  const cx = W / 2, cy = H / 2;
  const x1 = cx - (dx * scale) / 2, y1 = cy - (dy * scale) / 2;
  const x2 = cx + (dx * scale) / 2, y2 = cy + (dy * scale) / 2;

  return (
    <div className="vector-diagram">
      <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`}>
        <line x1={x1} y1={y1} x2={x2} y2={y2} stroke="var(--line)" strokeWidth="1.5" />
        <circle cx={x1} cy={y1} r="4.5" fill="var(--amber-bright)" />
        <circle cx={x2} cy={y2} r="4.5" fill="var(--court)" />
        <text x={x1} y={y1 - 9} textAnchor="middle" className="vd-label vd-anchor">{shortName(anchor.name)}</text>
        <text x={x2} y={y2 - 9} textAnchor="middle" className="vd-label vd-match">{shortName(match.player.name)}</text>
      </svg>
      <div className="vd-caption">cosine similarity {match.cosine.toFixed(3)}</div>
    </div>
  );
}

function shortName(name) {
  const parts = name.split(' ');
  return parts.length > 1 ? `${parts[0][0]}. ${parts[parts.length - 1]}` : name;
}

const NEIGHBOR_LABEL_COUNT = 8;
const OVERVIEW_RADIUS = 30;
const FOCUS_RADIUS = 7;

function Explore3D({ initialFocus }) {
  const containerRef = useRef(null);
  const canvasRef = useRef(null);
  const labelRefs = useRef({});
  const threeRef = useRef(null); // holds scene/camera/renderer/points across renders
  const camState = useRef({
    theta: 0.7, phi: 1.15,
    radius: OVERVIEW_RADIUS, radiusGoal: OVERVIEW_RADIUS,
    target: { x: 0, y: 0, z: 0 }, targetGoal: { x: 0, y: 0, z: 0 },
  });
  const dragRef = useRef({ dragging: false, lastX: 0, lastY: 0 });

  const [focus, setFocus] = useState(initialFocus || null);

  const neighbors = useMemo(() => {
    if (!focus) return [];
    return PLAYERS.filter(p => p.id !== focus.id)
      .map(p => ({ player: p, score: comparePlayers(focus, p).score }))
      .sort((a, b) => b.score - a.score)
      .slice(0, NEIGHBOR_LABEL_COUNT);
  }, [focus]);

  // One-time scene setup.
  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    const width = container.clientWidth, height = container.clientHeight;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(48, width / height, 0.1, 500);
    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(width, height);

    const grid = new THREE.GridHelper(48, 24, 0x2c323b, 0x2c323b);
    grid.position.y = -9;
    grid.material.transparent = true;
    grid.material.opacity = 0.35;
    scene.add(grid);

    const positions = new Float32Array(PLAYERS.length * 3);
    PLAYERS.forEach((p, i) => {
      positions[i * 3] = p.pca[0];
      positions[i * 3 + 1] = p.pca[1];
      positions[i * 3 + 2] = p.pca[2];
    });
    const cloudGeo = new THREE.BufferGeometry();
    cloudGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const cloudMat = new THREE.PointsMaterial({ color: 0x8b93a1, size: 0.34, transparent: true, opacity: 0.45, sizeAttenuation: true });
    const cloud = new THREE.Points(cloudGeo, cloudMat);
    scene.add(cloud);

    const neighborGeo = new THREE.BufferGeometry();
    neighborGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(NEIGHBOR_LABEL_COUNT * 3), 3));
    const neighborMat = new THREE.PointsMaterial({ color: 0xe2954f, size: 0.85, sizeAttenuation: true });
    const neighborPoints = new THREE.Points(neighborGeo, neighborMat);
    scene.add(neighborPoints);

    const focusGeo = new THREE.BufferGeometry();
    focusGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(3), 3));
    const focusMat = new THREE.PointsMaterial({ color: 0x4f9d7e, size: 1.15, sizeAttenuation: true });
    const focusPoint = new THREE.Points(focusGeo, focusMat);
    focusPoint.visible = false;
    scene.add(focusPoint);

    threeRef.current = { scene, camera, renderer, cloud, neighborPoints, focusPoint, raf: null };

    function applyCamera() {
      const s = camState.current;
      s.radius += (s.radiusGoal - s.radius) * 0.08;
      s.target.x += (s.targetGoal.x - s.target.x) * 0.08;
      s.target.y += (s.targetGoal.y - s.target.y) * 0.08;
      s.target.z += (s.targetGoal.z - s.target.z) * 0.08;
      const { theta, phi, radius, target } = s;
      camera.position.set(
        target.x + radius * Math.sin(phi) * Math.sin(theta),
        target.y + radius * Math.cos(phi),
        target.z + radius * Math.sin(phi) * Math.cos(theta)
      );
      camera.lookAt(target.x, target.y, target.z);
    }

    function updateLabels() {
      const rect = canvas.getBoundingClientRect();
      Object.entries(labelRefs.current).forEach(([id, el]) => {
        if (!el) return;
        const p = PLAYERS.find(pl => String(pl.id) === id);
        if (!p) return;
        const v = new THREE.Vector3(p.pca[0], p.pca[1], p.pca[2]).project(camera);
        if (v.z > 1) { el.style.display = 'none'; return; }
        const x = (v.x * 0.5 + 0.5) * rect.width;
        const y = (-v.y * 0.5 + 0.5) * rect.height;
        el.style.display = 'block';
        el.style.transform = `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px)`;
      });
    }

    function tick() {
      applyCamera();
      renderer.render(scene, camera);
      updateLabels();
      threeRef.current.raf = requestAnimationFrame(tick);
    }
    tick();

    function onPointerDown(e) {
      dragRef.current = { dragging: true, lastX: e.clientX, lastY: e.clientY };
    }
    function onPointerMove(e) {
      if (!dragRef.current.dragging) return;
      const dx = e.clientX - dragRef.current.lastX;
      const dy = e.clientY - dragRef.current.lastY;
      dragRef.current.lastX = e.clientX;
      dragRef.current.lastY = e.clientY;
      const s = camState.current;
      s.theta -= dx * 0.006;
      s.phi = Math.max(0.2, Math.min(Math.PI - 0.2, s.phi - dy * 0.006));
    }
    function onPointerUp() { dragRef.current.dragging = false; }
    function onWheel(e) {
      e.preventDefault();
      const s = camState.current;
      s.radiusGoal = Math.max(3, Math.min(55, s.radiusGoal + e.deltaY * 0.02));
    }
    canvas.addEventListener('pointerdown', onPointerDown);
    window.addEventListener('pointermove', onPointerMove);
    window.addEventListener('pointerup', onPointerUp);
    canvas.addEventListener('wheel', onWheel, { passive: false });

    function onResize() {
      const w = container.clientWidth, h = container.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    }
    const ro = new ResizeObserver(onResize);
    ro.observe(container);

    return () => {
      cancelAnimationFrame(threeRef.current.raf);
      canvas.removeEventListener('pointerdown', onPointerDown);
      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerup', onPointerUp);
      canvas.removeEventListener('wheel', onWheel);
      ro.disconnect();
      renderer.dispose();
    };
  }, []);

  // Fly camera + update highlighted points whenever focus changes.
  useEffect(() => {
    const t3 = threeRef.current;
    if (!t3) return;
    const s = camState.current;

    if (focus) {
      s.targetGoal = { x: focus.pca[0], y: focus.pca[1], z: focus.pca[2] };
      s.radiusGoal = FOCUS_RADIUS;

      const fpos = t3.focusPoint.geometry.attributes.position;
      fpos.array[0] = focus.pca[0]; fpos.array[1] = focus.pca[1]; fpos.array[2] = focus.pca[2];
      fpos.needsUpdate = true;
      t3.focusPoint.visible = true;

      const npos = t3.neighborPoints.geometry.attributes.position;
      neighbors.forEach((n, i) => {
        npos.array[i * 3] = n.player.pca[0];
        npos.array[i * 3 + 1] = n.player.pca[1];
        npos.array[i * 3 + 2] = n.player.pca[2];
      });
      for (let i = neighbors.length; i < NEIGHBOR_LABEL_COUNT; i++) {
        npos.array[i * 3] = 9999; npos.array[i * 3 + 1] = 9999; npos.array[i * 3 + 2] = 9999;
      }
      npos.needsUpdate = true;
    } else {
      s.targetGoal = { x: 0, y: 0, z: 0 };
      s.radiusGoal = OVERVIEW_RADIUS;
      t3.focusPoint.visible = false;
      const npos = t3.neighborPoints.geometry.attributes.position;
      for (let i = 0; i < NEIGHBOR_LABEL_COUNT; i++) {
        npos.array[i * 3] = 9999; npos.array[i * 3 + 1] = 9999; npos.array[i * 3 + 2] = 9999;
      }
      npos.needsUpdate = true;
    }
  }, [focus, neighbors]);

  return (
    <div className="explore-wrap">
      <div className="explore-toolbar">
        <PlayerAutocomplete onSelect={setFocus} excludeId={focus ? focus.id : null} />
        {focus && <button className="back-btn" onClick={() => setFocus(null)}>Reset view</button>}
      </div>
      <div className="explore-canvas-container" ref={containerRef}>
        <canvas ref={canvasRef} className="explore-canvas" />
        {focus && (
          <div className="vector-label vector-label-focus" ref={el => (labelRefs.current[focus.id] = el)}>
            {focus.name}
          </div>
        )}
        {neighbors.map(n => (
          <div
            key={n.player.id}
            className="vector-label"
            ref={el => (labelRefs.current[n.player.id] = el)}
            onClick={() => setFocus(n.player)}
          >
            {n.player.name} <span className="vl-score">{n.score.toFixed(0)}%</span>
          </div>
        ))}
        {!focus && (
          <div className="explore-hint">Search a player, or drag to rotate · scroll to zoom</div>
        )}
      </div>
      <div className="explore-footnote">
        Every dot is one of {PLAYERS.length} qualified players, plotted at the first 3 of the {DATA.pcaComponents} principal components that actually drive the similarity score (not a separate approximation) — together capturing about {Math.round(DATA.pcaVarianceExplained.reduce((a, b) => a + b, 0) * 100)}% of the real variation between players. Search a player to fly the camera to their neighborhood and label their {NEIGHBOR_LABEL_COUNT} closest statistical matches.
      </div>
    </div>
  );
}

function PlayerAutocomplete({ onSelect, excludeId }) {
  const [query, setQuery] = useState('');
  const [open, setOpen] = useState(false);
  const [highlight, setHighlight] = useState(0);
  const ref = useRef(null);

  const matches = useMemo(() => {
    if (!query.trim()) return [];
    const q = query.toLowerCase();
    return PLAYERS.filter(p => p.id !== excludeId && p.name.toLowerCase().includes(q))
      .sort((a, b) => a.name.toLowerCase().indexOf(q) - b.name.toLowerCase().indexOf(q))
      .slice(0, 8);
  }, [query, excludeId]);

  useEffect(() => {
    function handler(e) {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    }
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  function pick(p) {
    setQuery('');
    setOpen(false);
    onSelect(p);
  }

  function onKeyDown(e) {
    if (!open || matches.length === 0) return;
    if (e.key === 'ArrowDown') { e.preventDefault(); setHighlight(h => Math.min(h + 1, matches.length - 1)); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); setHighlight(h => Math.max(h - 1, 0)); }
    else if (e.key === 'Enter') { e.preventDefault(); pick(matches[highlight]); }
    else if (e.key === 'Escape') { setOpen(false); }
  }

  return (
    <div className="autocomplete" ref={ref}>
      <div className="search-row">
        <svg className="search-icon" width="18" height="18" viewBox="0 0 24 24" fill="none">
          <circle cx="11" cy="11" r="7" stroke="currentColor" strokeWidth="2" />
          <line x1="16.5" y1="16.5" x2="21" y2="21" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
        </svg>
        <input
          value={query}
          onChange={e => { setQuery(e.target.value); setOpen(true); setHighlight(0); }}
          onFocus={() => setOpen(true)}
          onKeyDown={onKeyDown}
          placeholder="Search a player…"
          className="search-input"
          aria-label="Search NBA player"
        />
      </div>
      {open && matches.length > 0 && (
        <div className="dropdown">
          {matches.map((p, i) => (
            <div
              key={p.id}
              className={"dropdown-item" + (i === highlight ? ' active' : '')}
              onMouseDown={() => pick(p)}
              onMouseEnter={() => setHighlight(i)}
            >
              <span className="dd-name">{p.name}</span>
              <span className="dd-team">{p.team}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

